<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {command,message,desktop} from '../api'
import {useDatabase} from '../stores/database'
import {templatePath,type UserTemplate} from '../userTemplates'
const props=defineProps<{open:boolean;entries:UserTemplate[];initialEntry?:UserTemplate;initialAction?:string}>()
const emit=defineEmits<{'update:open':[value:boolean];changed:[entries:UserTemplate[]]}>()
const db=useDatabase(),nodes=ref<UserTemplate[]>(props.entries),pane=ref(props.initialAction||'browse'),selected=ref(props.initialEntry?.id),kind=ref<number|undefined>(props.initialEntry?.templateId||undefined),parentId=ref<number>(),text=ref(''),query=ref(''),showRemoved=ref(false),busy=ref(false),error=ref(''),success=ref('')
watch(()=>props.entries,v=>nodes.value=v)
const entry=computed(()=>nodes.value.find(e=>e.id===selected.value))
const types=computed(()=>(db.info?.templates||[]).filter(t=>!t.hidden).map(t=>({label:t.name,value:t.id})))
const titles:Record<string,string>={browse:'Разделы справочника',create:'Новый раздел',edit:'Изменить раздел',move:'Переместить',copy:'Копировать ветвь',delete:'Удалить раздел?',restore:'Восстановить раздел?'}
const title=computed(()=>titles[pane.value]||'Справочник')
const parents=computed(()=>nodes.value.filter(e=>(e.folder||(pane.value==='create'&&e.id===selected.value))&&[...templatePath(e,nodes.value),e].every(p=>!p.deleted&&!p.hidden&&(!p.templateId||p.templateId===kind.value))&&(pane.value!=='move'||e.id!==selected.value&&!templatePath(e,nodes.value).some(p=>p.id===selected.value))).map(e=>({label:[...templatePath(e,nodes.value),e].map(p=>p.name).join(' / '),value:e.id})))
const folders=computed(()=>nodes.value.filter(e=>e.folder).map(e=>({entry:e,path:templatePath(e,nodes.value)})).filter(({entry:e,path})=>(showRemoved.value||![e,...path].some(p=>p.deleted||p.hidden))&&[...path,e].map(p=>p.name).join(' / ').toLowerCase().includes(query.value.toLowerCase())))
watch(kind,()=>parentId.value=undefined,{flush:'sync'})
function start(action:string,e?:UserTemplate){pane.value=action;selected.value=e?.id;kind.value=e?.templateId||undefined;text.value=e?.name||'';parentId.value=action==='create'?e?.id:undefined;error.value='';success.value=''}
if(props.initialAction&&props.initialAction!=='browse')start(props.initialAction,props.initialEntry)
const valid=computed(()=>['create','move','copy'].includes(pane.value)?Boolean(kind.value&&parentId.value&&(pane.value!=='create'||text.value.trim())):pane.value==='edit'?Boolean(text.value.trim()):Boolean(entry.value))
async function run(action=pane.value,e=entry.value,direction?:string){
 busy.value=true;error.value='';success.value=''
 try{const result=await command<{entry:UserTemplate;entries:UserTemplate[]}>('mutate_template_tree',{input:{action,id:action==='create'?null:e?.id??null,revision:action==='create'?null:e?.revision||0,templateId:kind.value??null,parentId:parentId.value??null,text:['edit','create'].includes(action)?text.value:null,folder:action==='create'?true:null,direction:direction??null}});nodes.value=result.entries;emit('changed',result.entries);pane.value='browse';success.value=action==='copy'?'Ветвь скопирована.':action==='move'?'Запись и её подразделы перемещены.':action==='delete'?'Раздел удалён. Его можно восстановить.':action==='restore'?'Раздел восстановлен. Отдельно удалённые потомки остаются удалёнными.':action==='order'?'Порядок изменён.':'Раздел сохранён.'}catch(e){error.value=message(e)}finally{busy.value=false}
}
function actions(e:UserTemplate){return [{label:'Новый подраздел',icon:'i-lucide-folder-plus',onSelect:()=>start('create',e)},...(!e.key?[{label:'Копировать ветвь',icon:'i-lucide-copy',onSelect:()=>start('copy',e)},{label:'Переместить',icon:'i-lucide-folder-input',onSelect:()=>start('move',e)},{label:'Выше в разделе',icon:'i-lucide-arrow-up',onSelect:()=>run('order',e,'up')},{label:'Ниже в разделе',icon:'i-lucide-arrow-down',onSelect:()=>run('order',e,'down')}]:[])]}
</script>
<template><UModal :open="open" @update:open="(v:boolean)=>{if(!busy)emit('update:open',v)}" :dismissible="!busy" :title="title" description="Разделы, вложенные заготовки и их порядок. Сохранённые исследования не изменяются." :ui="{content:'sm:max-w-3xl'}"><template #body><UAlert v-if="error" color="error" :description="error" class="mb-4"/><UAlert v-if="success" color="success" :description="success" class="mb-4"/>
<template v-if="pane==='browse'"><div class="flex flex-wrap gap-4 mb-5"><UInput v-model="query" placeholder="Найти раздел…" aria-label="Поиск разделов" class="flex-1"/><UButton icon="i-lucide-folder-plus" :disabled="busy||!desktop" @click="start('create')">Новый раздел</UButton></div><UCheckbox v-model="showRemoved" :ui="{root:'items-center',container:'h-auto',label:'block'}" label="Показать удалённые и скрытые разделы" class="mb-5"/><ul class="template-card-list template-folder-list"><li v-for="{entry:e,path} in folders" :key="e.id" class="template-card"><p class="template-card-path">{{path.map(p=>p.name).join(' / ')||'Справочник'}}</p><p class="template-card-text">{{e.name}}<span v-if="e.deleted||e.hidden" class="text-slate-500"> · Удалён</span></p><div class="template-card-actions"><template v-if="!e.key"><UButton v-if="e.deleted||e.hidden" icon="i-lucide-undo-2" variant="ghost" aria-label="Восстановить раздел" title="Восстановить раздел" :disabled="busy||!desktop" @click="run('restore',e)"/><template v-else><UButton icon="i-lucide-pencil" variant="ghost" color="neutral" aria-label="Изменить раздел" title="Изменить раздел" :disabled="busy||!desktop" @click="start('edit',e)"/><UButton icon="i-lucide-trash-2" variant="ghost" color="error" aria-label="Удалить раздел" title="Удалить раздел" :disabled="busy||!desktop" @click="start('delete',e)"/></template></template><UDropdownMenu :items="actions(e)"><UButton icon="i-lucide-ellipsis" variant="ghost" color="neutral" aria-label="Действия с разделом" title="Действия с разделом" :disabled="busy||!desktop||e.deleted||e.hidden"/></UDropdownMenu></div></li></ul><p v-if="!folders.length">Разделы не найдены.</p></template>
<div v-else class="grid gap-5"><p v-if="entry" class="preserve-lines">{{[...templatePath(entry,nodes),entry].map(p=>p.name).join(' / ')}}</p><UAlert v-if="pane==='create'&&entry&&!entry.folder" color="warning" description="Родительская заготовка станет разделом. Её текст сохранится как название раздела."/><p v-if="pane==='delete'">Раздел и его содержимое исчезнут из списка вставки. Отдельно удалённые записи не восстановятся при возврате раздела.</p><p v-if="pane==='copy'">Копируется вся ветвь с вложенными записями. Скрытые и удалённые записи сохранят своё состояние.</p><template v-if="['create','copy','move'].includes(pane)"><UFormField label="Вид исследования" required><USelect v-model="kind" :items="types" placeholder="Выберите исследование" class="w-full" :disabled="busy"/></UFormField><UFormField label="Раздел назначения" required><USelect v-model="parentId" :items="parents" placeholder="Выберите раздел" class="w-full" :disabled="busy||!kind"/></UFormField></template><UFormField v-if="['create','edit'].includes(pane)" label="Название раздела" required><UInput v-model="text" :maxlength="500" class="w-full" :disabled="busy"/></UFormField></div>
</template><template #footer><UButton variant="outline" color="neutral" :disabled="busy" @click="pane==='browse'?emit('update:open',false):pane='browse'">{{pane==='browse'?'Закрыть':'Назад'}}</UButton><UButton v-if="pane!=='browse'" :color="pane==='delete'?'error':'primary'" :disabled="busy||!valid||!desktop" :loading="busy" @click="run()">{{pane==='create'?'Создать':pane==='delete'?'Удалить':pane==='restore'?'Восстановить':pane==='copy'?'Копировать':pane==='move'?'Переместить':'Сохранить'}}</UButton></template></UModal></template>
